/**
 * The generated API client: openapi-fetch typed with the openapi-typescript output in `src/generated/schema.ts`
 * (regenerated by `./gradlew generateSdks`; never edit it by hand).
 */
import createClient, { type Client, type Middleware } from "openapi-fetch";
import type { components, operations, paths } from "./generated/schema.js";

export type { components, operations, paths };

/** Settings of {@link createForesignalClient}. */
export interface ForesignalClientOptions {
  /** The Foresignal base URL, e.g. `https://foresignal.example.org` (no `/v1`). */
  baseUrl: string;
  /** A Foresignal API token, sent as `Authorization: Bearer …`. */
  token?: string;
  /** Extra headers sent with every request. */
  headers?: Record<string, string>;
  /** The `fetch` to use (defaults to the global one). */
  fetch?: (input: Request) => Promise<Response>;
}

/** The typed client for every operation in docs/OpenAPI.json. */
export type ForesignalClient = Client<paths>;

/**
 * Creates the typed client, e.g. `const { data, error } = await client.GET("/v1/records", {params: {query: {kind: ["aircraft"]}}})`.
 */
export function createForesignalClient(options: ForesignalClientOptions): ForesignalClient {
  const client = createClient<paths>({
    baseUrl: options.baseUrl.replace(/\/+$/, ""),
    ...(options.headers ? { headers: options.headers } : {}),
    ...(options.fetch ? { fetch: options.fetch } : {}),
  });
  if (options.token) {
    const token = options.token;
    const auth: Middleware = {
      onRequest({ request }) {
        if (!request.headers.has("Authorization")) {
          request.headers.set("Authorization", `Bearer ${token}`);
        }
        return request;
      },
    };
    client.use(auth);
  }
  return client;
}
